/**********************************
**	 
**********************************/

void create_app_thread(void)
{
	tid_can_recv = rt_thread_create("can_recv",			thread_entry_can, 			RT_NULL,2048, 9, 20); 
  if(tid_can_recv != RT_NULL)
	{
    rt_thread_startup(tid_can_recv);
	}
	
	tid_shell = rt_thread_create("shell",			thread_entry_shell, 		NULL,2048, 10, 20); 
  if(tid_shell != RT_NULL)
	{
    rt_thread_startup(tid_shell);
	}
	
	tid_can_send = rt_thread_create("can_sned",thread_entry_can_send, 	RT_NULL,2048, 11, 20);
	if(tid_can_send != RT_NULL)
	{
    rt_thread_startup(tid_can_send);
	}
	
	tid_gnss = rt_thread_create("gnss",				 thread_entry_gnss, 		RT_NULL,1024, 12, 20);        
	if(tid_gnss != RT_NULL)
	{
    rt_thread_startup(tid_gnss);	
	}
	
	tid_lte = rt_thread_create("lte",				  thread_entry_lte,		RT_NULL,2048,	13,	20);       
  if(tid_lte != RT_NULL)  
	{
		rt_thread_startup(tid_lte);
	}
	
	tid_at = rt_thread_create("at",				thread_entry_at_parse, RT_NULL,1024,14, 20); 
  if(tid_at != RT_NULL)
	{
    rt_thread_startup(tid_at);
	}

	tid_packet = rt_thread_create("packet",		        thread_entry_packet, 		RT_NULL,2048, 15, 20);
  if(tid_packet != RT_NULL)
	{
    rt_thread_startup(tid_packet);
	}
	
	tid_gb4 = rt_thread_create("gb4",       thread_entry_gb4,   RT_NULL,2048,16,20);
	if(tid_gb4 != RT_NULL)
	{
		rt_thread_startup(tid_gb4);
	}
	
	tid_sms = rt_thread_create("sms",		 	thread_entry_sms, 	    RT_NULL,1536, 17, 20);
	if(tid_sms != RT_NULL)
	{
    rt_thread_startup(tid_sms);
	}
	
		
	tid_products = rt_thread_create("products",			thread_entry_products, 	NULL,2048, 18, 20);
	if(tid_products != NULL)
	{
    rt_thread_startup(tid_products);
	}
	
	tid_edge = rt_thread_create("edge",	thread_entry_edge, 	   RT_NULL,1024, 19, 20); 
		
	if(tid_edge != RT_NULL)
	{
		rt_thread_startup(tid_edge);	
	}
	
	tid_led = rt_thread_create("led",		thread_entry_led, 		RT_NULL,512, 29, 20); 
	if(tid_led != RT_NULL)
	{
    rt_thread_startup(tid_led);	
	}
}



/*********************************
**	
**********************************/

void delete_app_thread(void)
{
	if(tid_gnss != NULL)                 //
	{
		rt_thread_delete(tid_gnss);
	}
	
	if(tid_lte != NULL)
	{
		rt_thread_delete(tid_lte);
	}
	
	if(tid_at != NULL)
	{
		rt_thread_delete(tid_at);
	}
	
	if(tid_can_recv != NULL)
	{
		rt_thread_delete(tid_can_recv);
	}
	
	if(tid_packet != NULL)
	{
		rt_thread_delete(tid_packet);
	}
	
	
	if(tid_shell != NULL)
	{
		rt_thread_delete(tid_shell);
	}
	
	if(tid_can_send != NULL)
	{
		rt_thread_delete(tid_can_send);
	}
	
	if(tid_sms != NULL)
	{
		rt_thread_delete(tid_sms);
	}
	
	if(tid_led != NULL)
	{
		rt_thread_delete(tid_led);
	}
		
	if(tid_edge != NULL)
	{
		rt_thread_delete(tid_edge);
	}
		
	if(tid_gb4 != NULL)
	{
		rt_thread_delete(tid_gb4);
	}
	
	if(tid_products != NULL)
	{
		rt_thread_delete(tid_products);
	}
	
	rt_irq_timer3_resethook();            //
	
	if(unmount_files_sys() == 0)
	{
		rt_kprintf("-- unmount files sys .... ok\r\n");
	}
}


